package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RecommendationService {private final ProgressService progress;private final LearningHistoryService history;public RecommendationService(ProgressService p,LearningHistoryService h){progress=p;history=h;}
 public Recommendation recommend(Long courseId){var p=progress.summarize(courseId);if(!p.hasActivity())return new Recommendation("REVIEW_FLASHCARDS","Start with a flashcard review to create your first learning signal.","Review flashcards","/courses/"+courseId+"/flashcards");var weak=p.topics().stream().filter(t->!t.status().equals("STRONG")).min(Comparator.comparingDouble(ProgressSummary.TopicProgress::score));if(weak.isPresent())return new Recommendation("STUDY_TOPIC","Your weakest current signal is "+weak.get().topic()+" ("+weak.get().status()+").","Study this topic","/courses/"+courseId+"/materials");if(history.recent(courseId,1).stream().anyMatch(e->e.type().equals("FLASHCARD_REVIEW")))return new Recommendation("TAKE_QUIZ","Your recent flashcard activity is ready to be checked with retrieval practice.","Take a quiz","/courses/"+courseId+"/quizzes");return new Recommendation("FOLLOW_STUDY_PLAN","Keep following a balanced schedule for steady progress.","Open study plan","/courses/"+courseId+"/study-plan");}
}
